import{_ as n,l,o as a,c as i,v as o,p as d,x as t,d as s,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"Qwen2.5-Coder","description":"","frontmatter":{"title":"Qwen2.5-Coder","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/qwen25-coder.md","filePath":"llm/qwen25-coder.md","lastUpdated":1789023840000}'),B={name:"llm/qwen25-coder.md"};function m(E,e,h,A,u,g){const r=l("Mermaid");return a(),i("div",null,[e[1]||(e[1]=o('<h1 id="qwen2-5-coder" tabindex="-1">Qwen2.5-Coder <a class="header-anchor" href="#qwen2-5-coder" aria-label="Permalink to &quot;Qwen2.5-Coder&quot;">​</a></h1><div class="epigraph"><p>在 Qwen2.5 骨架上继续预训练超过 5.5 万亿 token：文件级填空、仓库级拼接、再加一份按清单打分的指令数据，代码能力与通识、数学一起保住。</p><footer>—— Hui 等，Qwen2.5-Coder Technical Report，arXiv:2409.12186</footer></div><p>Qwen2.5-Coder 是通义在 CodeQwen1.5 之后的代码专线，开源六档：<strong>0.5B、1.5B、3B、7B、14B、32B</strong>，Base 与 Instruct 成对放出。架构与词表继承 <a href="/llm/qwen-evolution">Qwen2.5</a>——<a href="/llm/gqa">GQA</a>、<a href="/llm/swiglu">SwiGLU</a>、<a href="/llm/rope">RoPE</a>、QKV bias、<a href="/llm/rmsnorm">RMSNorm</a>——专文贡献不在换注意力公式，而在 <strong>5.5T 代码向语料怎么造、文件级与仓库级怎么接、指令数据怎么验</strong>。旗舰 32B-Instruct 在报告叙事里对标当时开源代码模型的第一档，并声称在多项代码任务上接近 GPT-4o；小档覆盖边侧补全。本篇写 Hui 等人报告里的数据与训练工序，不把 GQA 或 YaRN 再展开成并列理论。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>代码模型若只喂 GitHub 源文件，会同时丢掉三样东西：教程与 API 文档里的自然语言接地、仓库里跨文件的 import 图、以及「中间缺一块」的 IDE 补全分布。纯下一 token 预训练对文件头到文件尾的因果续写很熟，对 prefix–suffix 夹一道空洞的 FIM 不熟；把整仓文件随机打散，模型也学不会「这个函数的实现在另一个文件」。CodeQwen1.5 已经证明专线有用，但尺寸档位少、语料与指令工序不够厚，对闭源旗舰仍有缺口。</p><p>另一条约束是<strong>不要训成只会写代码的窄模型</strong>。下游助手既要 HumanEval，也要解释报错、算一点数学、用中文讲清楚。把代码比例拉到 100% 会伤通识；反过来，网页噪声掺多了，补全会开始说人话。报告用 7B 扫三种配比，最后钉在代码 / 文本 / 数学 = 70 / 20 / 10。</p><h3 id="从单文件因果到仓库几何" tabindex="-1">从单文件因果到仓库几何 <a class="header-anchor" href="#从单文件因果到仓库几何" aria-label="Permalink to &quot;从单文件因果到仓库几何&quot;">​</a></h3><p>文件级预训练窗口 8192，目标是下一 token 预测加 FIM（Fill-in-the-Middle，Bavarian 等；解码形态见 <a href="/llm/fim-decode">FIM decode</a>）。仓库级要把上下文拉到 32768，RoPE 基数从 \\(10^4\\) 调到 \\(10^6\\)，再用 <a href="/llm/yarn">YaRN</a> 外推到 131072——外推机制见专文，这里只记报告的用法：长窗是为了把 <code>&lt;|repo_name|&gt;</code> 与 <code>&lt;|file_sep|&gt;</code> 隔开的多文件序列装进去，而不是另发明一种位置编码。</p><p><span class="marginnote">六档共享词表 151646，并新增 FIM 与仓库控制符（<code>&lt;|fim_prefix|&gt;</code> / <code>&lt;|fim_middle|&gt;</code> / <code>&lt;|fim_suffix|&gt;</code> / <code>&lt;|fim_pad|&gt;</code>、<code>&lt;|repo_name|&gt;</code>、<code>&lt;|file_sep|&gt;</code>）。换尺寸不必换 tokenizer；缺这些特殊符，仓库级打包在推理侧对不齐训练分布。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>预训练数据称作 Qwen2.5-Coder-Data，五类来源。<strong>源码</strong>：2024 年 2 月前的公开 GitHub，覆盖 92 种语言，规则过滤接近 StarCoder2 / DeepSeek-Coder；另收 PR、Commit、Jupyter、Kaggle。<strong>文本–代码接地</strong>：从 Common Crawl 召回文档、教程、博客。报告不用「按 URL 多段召回」当主策略，而做由粗到细的层级过滤：每一级用 fastText 一类小分类器卡一个质量维度，留下的数据自然带质量分数，便于配比。他们观察到大模型当过滤器并不明显更好——小模型更盯表面特征，避免把语义复杂度误当成质量。该管线迭代四轮后，1.5B 在 HumanEval 与 MBPP 上的平均分从 41.6% 升到 46.8%。</p><p><strong>合成数据</strong>：用前代 CodeQwen1.5 大规模生成，再用执行器校验，只留能跑通的代码，压幻觉。<strong>数学</strong>直接并入 Qwen2.5-Math 的预训练语料；<strong>通识文本</strong>取自 Qwen2.5，并剥掉其中的代码段以免与源码重复计数。配比实验（表 3）显示 100% 代码在纯代码榜上并不领先，70:20:10 的综合平均最高。最终约 5.2T token 进入文件级阶段。</p><h3 id="三阶段-文件、仓库、指令" tabindex="-1">三阶段：文件、仓库、指令 <a class="header-anchor" href="#三阶段-文件、仓库、指令" aria-label="Permalink to &quot;三阶段：文件、仓库、指令&quot;">​</a></h3><p>文件级：5.2T、长度 8192、NTP + 文件级 FIM。仓库级：约 300B 高质量长代码，窗口 32K，FIM 升到仓库级（格式跟随 Lozhkov 等 StarCoder2 的多文件填空）。指令阶段不再堆 token 规模，而堆<strong>可验证的任务覆盖</strong>。</p><p>指令数据几条并行管线。用微调过的 CodeBERT 做近百种语言识别：主流语言保留，长尾随机丢一部分；几乎不含代码的样本会伤 MultiPL-E / McEval，大部分去掉。无监督 GitHub 片段（≤1024 token）先让 LLM 写出「题」，再让代码模型写「答」，再用评分模型滤低质；并混入 McEval-Instruct 一类开源多语指令。多语言上，报告提出<strong>语言专用智能体</strong>：每个语言一个 agent，带自己的指令种子与生成历史（避免近重复），再按协议交叉讨论，把一种语言里的题型迁到另一种，或合成新语言的指令。质量用清单加权：问答一致性、是否在计算机域、难度、是否含代码、语法与逻辑正确、命名与缩进、注释、可学性。最后用多语言沙箱做静态检查（AST 解析失败即丢）并对自包含算法题自动生成单测。</p>',15)),(a(),d(c,null,{default:t(()=>[p(r,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E6%BA%90%E7%A0%81%20%2F%20PR%20%2F%20Notebook%22%5D%20--%3E%20MIX%5B%2270%25%20%E4%BB%A3%E7%A0%81%20%2B%2020%25%20%E6%96%87%E6%9C%AC%20%2B%2010%25%20%E6%95%B0%E5%AD%A6%22%5D%0A%20%20WEB%5B%22CC%20%E6%96%87%E6%9C%AC-%E4%BB%A3%E7%A0%81%E5%B1%82%E7%BA%A7%E8%BF%87%E6%BB%A4%22%5D%20--%3E%20MIX%0A%20%20SYN%5B%22CodeQwen1.5%20%E5%90%88%E6%88%90%20%2B%20%E6%89%A7%E8%A1%8C%E5%99%A8%22%5D%20--%3E%20MIX%0A%20%20MIX%20--%3E%20F%5B%22%E6%96%87%E4%BB%B6%E7%BA%A7%208K%EF%BC%9ANTP%20%2B%20FIM%22%5D%0A%20%20F%20--%3E%20R%5B%22%E4%BB%93%E5%BA%93%E7%BA%A7%2032K%EF%BC%9Arepo%20FIM%22%5D%0A%20%20R%20--%3E%20I%5B%22%E6%8C%87%E4%BB%A4%EF%BC%9A%E5%A4%9A%E8%AF%AD%20agent%20%2B%20%E6%B8%85%E5%8D%95%20%2B%20%E6%B2%99%E7%AE%B1%22%5D%0A%20%20I%20--%3E%20OUT%5B%220.5B%E2%80%9332B%20Instruct%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p><span class="marginnote">3B 的中间维（4864）比 1.5B（8960）更窄、层数更多（36 vs 28），不是「参数量单调加宽」。读表 1 时按列对照，不要用 7B 的 3584 隐维去口算 32B。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>文件级 FIM 让模型在训练分布里见到「已知前后文、未知中段」，与 IDE 的行内补全同构；仓库级把同一 repo 的多文件用分隔符串起来，import 与被引用定义可以落在同一 32K 窗口内，跨文件补全才有键可查。层级过滤给接地文档打分，等于在预训练混合里插入一条可调的质量轴：后段留下的文档更干净，前段仍提供覆盖。执行器过滤合成数据，把「看起来像代码」从「能通过运行」里切开——这是相对纯蒸馏的关键差异。</p><p>指令侧的清单不是单一 LLM-as-judge 分数。一致性、正确性、可学性会打架：很难但错误的题不该高分，无代码的计算机史问答也不该占满预算。多语 sandbox 只喂自包含片段，避免把「缺环境就跑不了」的真实工程文件误杀。语言 agent 的记忆库降低近重复，交叉讨论则把稀缺语言的题型从富语言迁过来，而不是为每种语言单独雇标注。</p><h3 id="特殊符只改序列-不改核" tabindex="-1">特殊符只改序列，不改核 <a class="header-anchor" href="#特殊符只改序列-不改核" aria-label="Permalink to &quot;特殊符只改序列，不改核&quot;">​</a></h3><p>后训练之后，模型仍是因果解码器：FIM 靠特殊符改写序列顺序，而不是改注意力核。128K 推理依赖与 Qwen2.5 相同的 YaRN 外推；若服务端没用匹配实现，仓库级 32K 训练也不会自动变成 128K 可用。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>报告评测覆盖生成、补全、推理、修复十多个基准，强调同尺寸开源 SOTA。不要把 0.5B 的 HumanEval 拿去对 32B 的叙事，也不要把云上 Qwen2.5-Coder 产品快照与开源权重当成同一检查点。合成数据过执行器仍可能过拟合「短自包含题」；真实仓库的构建系统、私有依赖、生成代码许可，报告解决不了。70:20:10 是 7B 上的扫描结果外推到全系列，更小模型对数学配比的敏感度未必相同。</p><p>许可证按当时模型卡：系列以允许商用的宽松许可为目标，具体条款以 Hugging Face / ModelScope 页面为准。Artifacts 与代码助手是报告里的产品演示，不是新的损失函数。</p><p><span class="marginnote">仓库级 FIM 的分隔符必须与训练一致。自行把多文件用 <code>###</code> 拼接，等于把 <code>&lt;|file_sep|&gt;</code> 的位置统计作废，补全质量会先掉一截再谈模型强不强。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Qwen2.5-Coder 在 Qwen2.5 架构上用约 5.5T token 继续预训练，开源 0.5B 至 32B。</li><li>数据贡献是层级过滤的文本–代码接地、可执行合成、以及 70:20:10 的代码–文本–数学混合。</li><li>训练分文件级 8K（NTP+FIM）与仓库级 32K（repo FIM + 基数 \\(10^6\\)），推理侧 YaRN 到 128K。</li><li>指令数据靠多语 agent、清单打分与沙箱单测，而不是只堆开源指令集。</li><li>出处：Hui 等，<em>Qwen2.5-Coder Technical Report</em>，arXiv:2409.12186，2024。</li></ul>',12))])}const C=n(B,[["render",m]]);export{_ as __pageData,C as default};
